use std::hint::black_box;
use std::time::Instant;

const RAW_DATA: &str = "";
const DATA: &[u8] = RAW_DATA.as_bytes();

pub fn find_first_fourteen(input: &[u8]) -> usize {
  let mut check: u32 = 0;

  let mut i: usize = 13;
  while i < input.len() {
    let end = i - 13;
    let window = &input[end..=i];

    let mut w: usize = 13;
    while w < 14 {
      let marker: u32 = 1 << (window[w] & 31);

      if (check & marker) == 0 {
        check = check | marker;
      } else {
        i = end + w + 14;
        check = 0;
        break;
      }

      if w == 0 {
        return i + 1;
      }

      w -= 1;
    }
  }

  return 0;
}

fn main() {
  let mut start = 0;

  let before = Instant::now();
  for _ in 0..100 {
    start = black_box(find_first_fourteen(black_box(DATA)));
  }
  let average = before.elapsed().as_nanos() as f64 / 100.0;

  println!("findStart found {} and took {} nanoseconds", start, average);
}
